CREATE UNIQUE INDEX "purchase_invoices_supplier_bill_fy_key" ON "purchase_invoices" USING btree ("supplier_id",lower(regexp_replace(btrim("supplier_invoice_no"), '[[:space:]]+', ' ', 'g')),(extract(year from (("document_date" at time zone 'UTC') - interval '3 months'))),("invoice_type" in ('Purchase Return', 'Credit Note'))) WHERE btrim("purchase_invoices"."supplier_invoice_no") <> '';